INSERT INTO "wanjiedaoyou_baixiao_questions" ("knowledge_key", "question", "status") VALUES
  ('mulan-pair', '{"knowledgeKey":"mulan-pair","category":"literature","difficulty":"easy","kind":"choice","prompt":"《木兰诗》的结尾用哪种动物成双奔跑来作比？","options":["兔","鹿","雁","马"],"correct":0,"explanation":"雄兔与雌兔并跑，诗以此回应同伴未辨出木兰身份。","source":"《乐府诗集·木兰诗》"}'::jsonb, 'published'),
  ('spring-zhuxi', '{"knowledgeKey":"spring-zhuxi","category":"literature","difficulty":"easy","kind":"choice","prompt":"“等闲识得东风面”以哪句收尾？","options":["万紫千红总是春","春色满园关不住","拂堤杨柳醉春烟","春来江水绿如蓝"],"correct":0,"explanation":"这两句是朱熹《春日》的后半首。","source":"朱熹《春日》"}'::jsonb, 'published'),
  ('peach-surname', '{"knowledgeKey":"peach-surname","category":"literature","difficulty":"easy","kind":"choice","prompt":"陶渊明笔下最先发现桃花源的人以什么为业？","options":["捕鱼","伐木","采药","牧马"],"correct":0,"explanation":"《桃花源记》开篇写武陵人捕鱼为业。","source":"陶渊明《桃花源记》"}'::jsonb, 'published'),
  ('five-character', '{"knowledgeKey":"five-character","category":"literature","difficulty":"easy","kind":"judgment","prompt":"“海内存知己，天涯若比邻”两句各有五个字。","options":["是","否"],"correct":0,"explanation":"除标点外，上下两句各五字。","source":"王勃《送杜少府之任蜀州》"}'::jsonb, 'published'),
  ('west-journey-pig', '{"knowledgeKey":"west-journey-pig","category":"literature","difficulty":"easy","kind":"choice","prompt":"《西游记》师徒之中，常用九齿钉耙的是谁？","options":["猪八戒","沙悟净","孙悟空","白龙马"],"correct":0,"explanation":"九齿钉耙是猪八戒的兵器。","source":"吴承恩《西游记》"}'::jsonb, 'published'),
  ('song-qingming', '{"knowledgeKey":"song-qingming","category":"literature","difficulty":"easy","kind":"choice","prompt":"杜牧《清明》中，诗人向牧童打听的是哪一种去处？","options":["酒家","客栈","书院","驿站"],"correct":0,"explanation":"诗中写“借问酒家何处有”。","source":"杜牧《清明》"}'::jsonb, 'published'),
  ('dragonboat-fruit', '{"knowledgeKey":"dragonboat-fruit","category":"literature","difficulty":"easy","kind":"choice","prompt":"“榴花忽已繁”中“榴花”开什么花？","options":["石榴花","杏花","梨花","海棠花"],"correct":0,"explanation":"“榴”指石榴，初夏常见开花。","source":"元稹《表夏十首》"}'::jsonb, 'published'),
  ('luchai-sound', '{"knowledgeKey":"luchai-sound","category":"literature","difficulty":"easy","kind":"choice","prompt":"王维《鹿柴》里，空山中先听到了什么？","options":["人语","松涛","钟声","鹿鸣"],"correct":0,"explanation":"诗的前两句写空山看不见人，只听到人的说话声。","source":"王维《鹿柴》"}'::jsonb, 'published'),
  ('liuyuxi-moss', '{"knowledgeKey":"liuyuxi-moss","category":"literature","difficulty":"medium","kind":"choice","prompt":"《陋室铭》用青苔写台阶，用什么写映入帘中的绿色？","options":["草色","竹影","池水","柳丝"],"correct":0,"explanation":"原文为“苔痕上阶绿，草色入帘青”。","source":"刘禹锡《陋室铭》"}'::jsonb, 'published'),
  ('fan-fisher', '{"knowledgeKey":"fan-fisher","category":"literature","difficulty":"medium","kind":"choice","prompt":"范仲淹《江上渔者》写江上往来的人爱吃哪种鱼？","options":["鲈鱼","鳜鱼","鲤鱼","鲫鱼"],"correct":0,"explanation":"“江上往来人，但爱鲈鱼美”，由食客引出渔者的辛苦。","source":"范仲淹《江上渔者》"}'::jsonb, 'published'),
  ('zhengxie-rock', '{"knowledgeKey":"zhengxie-rock","category":"literature","difficulty":"medium","kind":"choice","prompt":"郑燮《竹石》中，竹子的根扎在什么地方？","options":["破岩","河泥","松枝","沙洲"],"correct":0,"explanation":"“咬定青山不放松，立根原在破岩中。”","source":"郑燮《竹石》"}'::jsonb, 'published'),
  ('two-lakes', '{"knowledgeKey":"two-lakes","category":"literature","difficulty":"medium","kind":"judgment","prompt":"《湖心亭看雪》开头写的是西湖。","options":["是","否"],"correct":0,"explanation":"原文记载作者当时住在西湖一带。","source":"张岱《湖心亭看雪》"}'::jsonb, 'published'),
  ('kuafu-stick', '{"knowledgeKey":"kuafu-stick","category":"literature","difficulty":"medium","kind":"choice","prompt":"《山海经》的夸父逐日故事里，夸父丢弃的手杖化作什么？","options":["邓林","赤水","长桥","巨石"],"correct":0,"explanation":"《海外北经》载“弃其杖，化为邓林”。","source":"《山海经·海外北经》"}'::jsonb, 'published'),
  ('cicada-purity', '{"knowledgeKey":"cicada-purity","category":"literature","difficulty":"medium","kind":"choice","prompt":"虞世南写“居高声自远”时，借哪种动物的声音寄意？","options":["蝉","鹤","雁","蛙"],"correct":0,"explanation":"这是虞世南《蝉》的第三句。","source":"虞世南《蝉》"}'::jsonb, 'published'),
  ('su-east-slope', '{"knowledgeKey":"su-east-slope","category":"literature","difficulty":"medium","kind":"choice","prompt":"“人生如梦，一尊还酹江月”出现在哪首词中？","options":["《念奴娇·赤壁怀古》","《水调歌头·明月几时有》","《江城子·密州出猎》","《定风波·莫听穿林打叶声》"],"correct":0,"explanation":"“酹江月”是《念奴娇·赤壁怀古》的结句。","source":"苏轼《念奴娇·赤壁怀古》"}'::jsonb, 'published'),
  ('autumn-jiangfeng', '{"knowledgeKey":"autumn-jiangfeng","category":"literature","difficulty":"medium","kind":"choice","prompt":"张继写“月落乌啼霜满天”时，夜半钟声从哪座寺传来？","options":["寒山寺","灵隐寺","白马寺","大相国寺"],"correct":0,"explanation":"诗中写姑苏城外的寒山寺。","source":"张继《枫桥夜泊》"}'::jsonb, 'published'),
  ('li-bai-wanglun', '{"knowledgeKey":"li-bai-wanglun","category":"literature","difficulty":"medium","kind":"choice","prompt":"《赠汪伦》中被用来衬托友情深厚的是什么？","options":["潭水的深度","桃花的数量","舟行的速度","山间的回声"],"correct":0,"explanation":"李白以桃花潭水深千尺衬托汪伦相送之情。","source":"李白《赠汪伦》"}'::jsonb, 'published'),
  ('han-yu-horse', '{"knowledgeKey":"han-yu-horse","category":"literature","difficulty":"medium","kind":"choice","prompt":"《马说》以千里马容易被埋没寓意人才难遇，文中的识马者是谁？","options":["伯乐","庖丁","匠石","师旷"],"correct":0,"explanation":"篇首先说“世有伯乐，然后有千里马”。","source":"韩愈《杂说四·马说》"}'::jsonb, 'published'),
  ('chuci-song', '{"knowledgeKey":"chuci-song","category":"literature","difficulty":"medium","kind":"choice","prompt":"《楚辞·九歌》中，篇名哪一个与江河水神直接相关？","options":["《河伯》","《山鬼》","《东君》","《国殇》"],"correct":0,"explanation":"河伯是古代神话中的河神。","source":"《楚辞·九歌》"}'::jsonb, 'published'),
  ('caopi-argument', '{"knowledgeKey":"caopi-argument","category":"literature","difficulty":"medium","kind":"choice","prompt":"“盖文章，经国之大业，不朽之盛事”出自哪篇文章？","options":["《典论·论文》","《文赋》","《过秦论》","《师说》"],"correct":0,"explanation":"这句话出自曹丕对文章价值的论述。","source":"曹丕《典论·论文》"}'::jsonb, 'published'),
  ('ouyang-drink', '{"knowledgeKey":"ouyang-drink","category":"literature","difficulty":"medium","kind":"choice","prompt":"“醉翁之意不在酒”之后，原文点明醉翁意在何处？","options":["山水之间","宾客之间","灯火之间","丝竹之间"],"correct":0,"explanation":"欧阳修写“在乎山水之间也”。","source":"欧阳修《醉翁亭记》"}'::jsonb, 'published'),
  ('lotus-between', '{"knowledgeKey":"lotus-between","category":"literature","difficulty":"medium","kind":"choice","prompt":"周敦颐以牡丹比作花中的富贵者，以荷花比作花中的什么人？","options":["君子","隐逸者","行旅者","长者"],"correct":0,"explanation":"《爱莲说》分别以菊、牡丹、莲比隐逸者、富贵者和君子。","source":"周敦颐《爱莲说》"}'::jsonb, 'published'),
  ('zhuangzi-breath', '{"knowledgeKey":"zhuangzi-breath","category":"literature","difficulty":"hard","kind":"choice","prompt":"《逍遥游》中，大鹏的双翼被比作什么？","options":["垂天之云","离弦之箭","越岭之风","飞溅之浪"],"correct":0,"explanation":"原文为“怒而飞，其翼若垂天之云”。","source":"《庄子·逍遥游》"}'::jsonb, 'published'),
  ('tao-return-field', '{"knowledgeKey":"tao-return-field","category":"literature","difficulty":"hard","kind":"choice","prompt":"“悟已往之不谏，知来者之可追”出自陶渊明哪篇作品？","options":["《归去来兮辞》","《五柳先生传》","《桃花源记》","《与子俨等疏》"],"correct":0,"explanation":"这两句在《归去来兮辞》序后正文开头处。","source":"陶渊明《归去来兮辞》"}'::jsonb, 'published'),
  ('zhang-ruoxu-line', '{"knowledgeKey":"zhang-ruoxu-line","category":"literature","difficulty":"hard","kind":"choice","prompt":"“江畔何人初见月”在《春江花月夜》中对应的下一句问什么？","options":["江月何年初照人","人生何处不相逢","相逢何必曾相识","明月何时照我还"],"correct":0,"explanation":"张若虚以两个相承的问句写江月和人世。","source":"张若虚《春江花月夜》"}'::jsonb, 'published'),
  ('wenxin-title', '{"knowledgeKey":"wenxin-title","category":"literature","difficulty":"hard","kind":"choice","prompt":"《文心雕龙》中专论创作时想象活动的是哪一篇？","options":["《神思》","《明诗》","《辨骚》","《通变》"],"correct":0,"explanation":"《神思》讨论文思如何越出眼前时空。","source":"刘勰《文心雕龙·神思》"}'::jsonb, 'published'),
  ('shiji-chapter', '{"knowledgeKey":"shiji-chapter","category":"literature","difficulty":"hard","kind":"choice","prompt":"《史记》未以列传记载项羽，收录项羽主要生平的是哪一体例？","options":["本纪","表","书","世家"],"correct":0,"explanation":"司马迁以《项羽本纪》记载项羽生平。","source":"《史记·项羽本纪》"}'::jsonb, 'published'),
  ('xunzi-boat', '{"knowledgeKey":"xunzi-boat","category":"literature","difficulty":"hard","kind":"choice","prompt":"《荀子·劝学》中，借舟楫所达到的是哪种结果？","options":["渡过江河","登上高山","听得更清","跑得更快"],"correct":0,"explanation":"原文以借舟楫能“绝江河”说明借助外物的作用。","source":"《荀子·劝学》"}'::jsonb, 'published'),
  ('xian-wall', '{"knowledgeKey":"xian-wall","category":"history","difficulty":"easy","kind":"choice","prompt":"大雁塔与小雁塔都位于今天的哪座城市？","options":["西安","洛阳","开封","太原"],"correct":0,"explanation":"两座古塔都在陕西西安。","source":"联合国教科文组织《丝绸之路：长安—天山廊道的路网》"}'::jsonb, 'published'),
  ('capital-song', '{"knowledgeKey":"capital-song","category":"history","difficulty":"easy","kind":"judgment","prompt":"北宋东京所在的是今天的开封。","options":["是","否"],"correct":0,"explanation":"北宋以开封府为东京。","source":"《宋史·地理志》"}'::jsonb, 'published'),
  ('grand-canal-hangzhou', '{"knowledgeKey":"grand-canal-hangzhou","category":"history","difficulty":"easy","kind":"choice","prompt":"京杭大运河名称里的“杭”指的是哪里？","options":["杭州","苏州","湖州","扬州"],"correct":0,"explanation":"京杭大运河的南端到杭州。","source":"中国大运河博物馆《大运河及其遗产》"}'::jsonb, 'published'),
  ('song-capital-south', '{"knowledgeKey":"song-capital-south","category":"history","difficulty":"easy","kind":"choice","prompt":"南宋临安府对应今天的哪座城市？","options":["杭州","绍兴","南京","苏州"],"correct":0,"explanation":"南宋的都城临安府在今天的杭州。","source":"《宋史·地理志》"}'::jsonb, 'published'),
  ('guangzhou-pearl', '{"knowledgeKey":"guangzhou-pearl","category":"history","difficulty":"easy","kind":"choice","prompt":"哪条河流的水系穿过广州入海？","options":["珠江","闽江","钱塘江","辽河"],"correct":0,"explanation":"广州位于珠江三角洲。","source":"广州市人民政府《自然地理》"}'::jsonb, 'published'),
  ('yungang-city', '{"knowledgeKey":"yungang-city","category":"history","difficulty":"easy","kind":"judgment","prompt":"云冈石窟位于黑龙江。","options":["是","否"],"correct":1,"explanation":"云冈石窟位于山西大同。","source":"联合国教科文组织《云冈石窟》"}'::jsonb, 'published'),
  ('dujiangyan-river', '{"knowledgeKey":"dujiangyan-river","category":"history","difficulty":"easy","kind":"choice","prompt":"都江堰借分流治理的是哪条江？","options":["岷江","雅砻江","嘉陵江","乌江"],"correct":0,"explanation":"都江堰的渠首从岷江分流。","source":"联合国教科文组织《青城山和都江堰》"}'::jsonb, 'published'),
  ('zhenghe-ming', '{"knowledgeKey":"zhenghe-ming","category":"history","difficulty":"medium","kind":"choice","prompt":"郑和船队首航西洋时，在位的是哪位明朝皇帝？","options":["明成祖","明仁宗","明宣宗","明英宗"],"correct":0,"explanation":"首航在永乐三年，永乐是明成祖年号。","source":"《明史·郑和传》"}'::jsonb, 'published'),
  ('monta-qin', '{"knowledgeKey":"monta-qin","category":"history","difficulty":"medium","kind":"choice","prompt":"常与“文景之治”并列的景帝属于哪个王朝？","options":["西汉","东汉","西晋","东晋"],"correct":0,"explanation":"文帝与景帝均是西汉皇帝。","source":"《史记·孝景本纪》"}'::jsonb, 'published'),
  ('xiyu-han', '{"knowledgeKey":"xiyu-han","category":"history","difficulty":"medium","kind":"choice","prompt":"张骞第一次出使西域时，承担的是哪个王朝的使命？","options":["西汉","东汉","唐朝","北魏"],"correct":0,"explanation":"张骞奉汉武帝之命出使西域。","source":"《史记·大宛列传》"}'::jsonb, 'published'),
  ('wudang-hubei', '{"knowledgeKey":"wudang-hubei","category":"history","difficulty":"medium","kind":"judgment","prompt":"武当山古建筑群在今天的湖北省。","options":["是","否"],"correct":0,"explanation":"武当山在湖北十堰。","source":"联合国教科文组织《武当山古建筑群》"}'::jsonb, 'published'),
  ('potala-lhasa', '{"knowledgeKey":"potala-lhasa","category":"history","difficulty":"medium","kind":"choice","prompt":"布达拉宫位于哪座城市？","options":["拉萨","日喀则","林芝","昌都"],"correct":0,"explanation":"布达拉宫坐落于拉萨古城的红山上。","source":"联合国教科文组织《拉萨布达拉宫历史建筑群》"}'::jsonb, 'published'),
  ('qingshan-tai', '{"knowledgeKey":"qingshan-tai","category":"history","difficulty":"medium","kind":"choice","prompt":"泰山所在的省份是哪里？","options":["山东","山西","河南","河北"],"correct":0,"explanation":"泰山位于山东省泰安市。","source":"联合国教科文组织《泰山》"}'::jsonb, 'published'),
  ('zhaozhou-water', '{"knowledgeKey":"zhaozhou-water","category":"history","difficulty":"medium","kind":"choice","prompt":"赵州桥是一座跨河的石拱桥，它跨过哪条河？","options":["洨河","汾河","永定河","滹沱河"],"correct":0,"explanation":"赵州桥又称安济桥，跨河北赵县洨河。","source":"河北博物院《赵州桥》"}'::jsonb, 'published'),
  ('chibi-era', '{"knowledgeKey":"chibi-era","category":"history","difficulty":"medium","kind":"choice","prompt":"赤壁之战发生时，汉朝处于哪一时期？","options":["东汉末年","西汉初年","西汉末年","东汉初年"],"correct":0,"explanation":"此战发生于汉献帝建安十三年。","source":"《三国志·吴书·周瑜传》"}'::jsonb, 'published'),
  ('zuqiu-river', '{"knowledgeKey":"zuqiu-river","category":"history","difficulty":"medium","kind":"choice","prompt":"长江从高原向下游流经宜宾。宜宾属于哪个省？","options":["四川","重庆","贵州","湖北"],"correct":0,"explanation":"长江干流在宜宾与岷江相汇，宜宾属四川。","source":"宜宾市人民政府《宜宾概况》"}'::jsonb, 'published'),
  ('qin-water', '{"knowledgeKey":"qin-water","category":"history","difficulty":"medium","kind":"choice","prompt":"秦代为联通湘江水系与漓江水系所修的水道叫什么？","options":["灵渠","郑国渠","通济渠","白渠"],"correct":0,"explanation":"灵渠在今广西兴安，连接长江和珠江两大水系。","source":"《史记·平津侯主父列传》及兴安灵渠资料"}'::jsonb, 'published'),
  ('duhu-zheng', '{"knowledgeKey":"duhu-zheng","category":"history","difficulty":"hard","kind":"choice","prompt":"唐朝先设安西都护府，最初治所在哪一带？","options":["交河城","敦煌","晋阳","江都"],"correct":0,"explanation":"安西都护府最初设于西州交河城。","source":"《旧唐书·地理志》"}'::jsonb, 'published'),
  ('hanzhong-hanwater', '{"knowledgeKey":"hanzhong-hanwater","category":"history","difficulty":"hard","kind":"choice","prompt":"汉江发源地所在的陕西省，哪座城市与其上游河谷有直接关系？","options":["汉中","咸阳","铜川","榆林"],"correct":0,"explanation":"汉中盆地为汉江上游的重要河谷盆地。","source":"汉中市人民政府《自然地理》"}'::jsonb, 'published'),
  ('dunhuang-slip', '{"knowledgeKey":"dunhuang-slip","category":"history","difficulty":"hard","kind":"choice","prompt":"悬泉置在敦煌附近，出土的汉简主要记录什么机构的事务？","options":["驿置","太学","盐场","铸币局"],"correct":0,"explanation":"悬泉置是丝绸之路上的驿站，简牍保存接待和传递等记录。","source":"甘肃简牍博物馆《悬泉汉简》"}'::jsonb, 'published'),
  ('famen-province', '{"knowledgeKey":"famen-province","category":"history","difficulty":"hard","kind":"choice","prompt":"法门寺地宫出土的唐代秘色瓷收藏地在陕西，寺院位于哪一县？","options":["扶风","蓝田","周至","蒲城"],"correct":0,"explanation":"法门寺位于陕西宝鸡市扶风县。","source":"法门寺博物馆馆情介绍"}'::jsonb, 'published'),
  ('huangshan-crest', '{"knowledgeKey":"huangshan-crest","category":"history","difficulty":"hard","kind":"choice","prompt":"黄山风景区的三大主峰包括光明顶、天都峰，还包括哪座？","options":["莲花峰","祝融峰","玉皇顶","朝阳峰"],"correct":0,"explanation":"莲花峰与光明顶、天都峰并称黄山三大主峰。","source":"黄山风景区《黄山概况》"}'::jsonb, 'published'),
  ('kaicheng-stone', '{"knowledgeKey":"kaicheng-stone","category":"history","difficulty":"hard","kind":"choice","prompt":"唐代《开成石经》今天主要收藏在哪里？","options":["西安碑林","曲阜孔庙","洛阳龙门","南京朝天宫"],"correct":0,"explanation":"开成石经是西安碑林的重要藏品。","source":"西安碑林博物馆《开成石经》"}'::jsonb, 'published'),
  ('lantern-double', '{"knowledgeKey":"lantern-double","category":"riddle","difficulty":"easy","kind":"choice","prompt":"书童把 6 盏纸灯排成一行，吹灭中间两盏，桌上还摆着几盏灯？","options":["6 盏","4 盏","2 盏","8 盏"],"correct":0,"explanation":"吹灭的是火焰，纸灯仍在桌上。","source":"百晓盛会原创"}'::jsonb, 'published'),
  ('reversed-step', '{"knowledgeKey":"reversed-step","category":"riddle","difficulty":"easy","kind":"choice","prompt":"石阶上共站着三个童子。最矮的向后走两步，童子总数是多少？","options":["三个","一个","两个","五个"],"correct":0,"explanation":"改变位置不会改变人数。","source":"百晓盛会原创"}'::jsonb, 'published'),
  ('seal-open', '{"knowledgeKey":"seal-open","category":"riddle","difficulty":"easy","kind":"choice","prompt":"师徒共拿来三只印匣，开了两只。还有几只印匣未打开？","options":["一只","两只","三只","零只"],"correct":0,"explanation":"三只减去两只已打开的，还剩一只。","source":"百晓盛会原创"}'::jsonb, 'published'),
  ('sleeve-cats', '{"knowledgeKey":"sleeve-cats","category":"riddle","difficulty":"medium","kind":"choice","prompt":"两只猫都在朝东的门外，其中一只的尾尖朝西。问一定有几只猫在门外？","options":["两只","一只","零只","三只"],"correct":0,"explanation":"两只猫的位置已在题首给出，尾巴朝向不会改变位置。","source":"百晓盛会原创"}'::jsonb, 'published'),
  ('shadow-noon', '{"knowledgeKey":"shadow-noon","category":"riddle","difficulty":"medium","kind":"choice","prompt":"你只带着一把伞和一面镜子。想把窗外照进来的阳光反射到背阴的案角，该用哪件？","options":["镜子","伞","两件都必须用","两件都不能用"],"correct":0,"explanation":"转动镜子能改变反射光的方向。","source":"百晓盛会原创"}'::jsonb, 'published'),
  ('ink-digits', '{"knowledgeKey":"ink-digits","category":"riddle","difficulty":"medium","kind":"choice","prompt":"一册书有 50 页，从 1 写到 50 的所有页码中，数字 0 写了几次？","options":["5 次","4 次","6 次","10 次"],"correct":0,"explanation":"10、20、30、40、50 的末位各有一个 0。","source":"百晓盛会原创"}'::jsonb, 'published'),
  ('chess-turn', '{"knowledgeKey":"chess-turn","category":"riddle","difficulty":"medium","kind":"judgment","prompt":"三人都只下一盘棋，每盘必须恰有两名不同棋手，能让三人都下到吗？","options":["是","否"],"correct":1,"explanation":"每盘消耗两个人的一次机会，奇数个机会无法两两配对。","source":"百晓盛会原创"}'::jsonb, 'published'),
  ('two-baskets', '{"knowledgeKey":"two-baskets","category":"riddle","difficulty":"medium","kind":"choice","prompt":"两只篮子共有 12 枚果子。甲篮比乙篮多 4 枚，甲篮有几枚？","options":["8 枚","6 枚","4 枚","10 枚"],"correct":0,"explanation":"先去掉多出的 4 枚，余下两篮各 4 枚，甲再加 4 枚。","source":"百晓盛会原创"}'::jsonb, 'published'),
  ('stone-label', '{"knowledgeKey":"stone-label","category":"riddle","difficulty":"medium","kind":"choice","prompt":"四个匣子编号 1 到 4。真珠只在一个匣中，匣号是偶数，且比 3 小。它在哪个匣中？","options":["2 号","1 号","3 号","4 号"],"correct":0,"explanation":"两个偶数编号中，只有 2 小于 3。","source":"百晓盛会原创"}'::jsonb, 'published'),
  ('empty-measure', '{"knowledgeKey":"empty-measure","category":"riddle","difficulty":"medium","kind":"choice","prompt":"壶中有水半升，桌上三个空杯各可盛半升。把壶中的水平均倒入三个杯子，每杯有多少？","options":["六分之一升","三分之一升","二分之一升","三分之二升"],"correct":0,"explanation":"半升分成三等份，每份六分之一升。","source":"百晓盛会原创"}'::jsonb, 'published'),
  ('scroll-self', '{"knowledgeKey":"scroll-self","category":"riddle","difficulty":"medium","kind":"choice","prompt":"题签上写着“本签有七个字”。只计算引号里的汉字，实际上有几个？","options":["六个","七个","八个","五个"],"correct":0,"explanation":"本、签、有、七、个、字，共六个。","source":"百晓盛会原创"}'::jsonb, 'published'),
  ('abacus-repeat', '{"knowledgeKey":"abacus-repeat","category":"riddle","difficulty":"medium","kind":"choice","prompt":"一道门要先响一次钟，再依次响两次鼓，末尾再响一次钟。从开始到开门共响几次？","options":["四次","三次","两次","五次"],"correct":0,"explanation":"钟两次，鼓两次，共四次。","source":"百晓盛会原创"}'::jsonb, 'published'),
  ('paired-socks', '{"knowledgeKey":"paired-socks","category":"riddle","difficulty":"hard","kind":"choice","prompt":"匣中有红、青、白袜各两只。不看颜色，至少取出几只，才能保证其中有两只同色？","options":["4 只","3 只","5 只","6 只"],"correct":0,"explanation":"前三只可能各色一只，第四只必与其中一只同色。","source":"百晓盛会原创"}'::jsonb, 'published'),
  ('bridge-tokens', '{"knowledgeKey":"bridge-tokens","category":"riddle","difficulty":"hard","kind":"choice","prompt":"九枚铜钱中只有一枚较轻，余者一样重。只有一架无砝码天平，至少称几次能保证找到轻钱？","options":["2 次","1 次","3 次","4 次"],"correct":0,"explanation":"先分三组各三枚称两组，找出轻钱所在组，再从组三枚中称两枚。一次只有三种结果，无法区分九枚。","source":"百晓盛会原创"}'::jsonb, 'published'),
  ('gates-order', '{"knowledgeKey":"gates-order","category":"riddle","difficulty":"hard","kind":"choice","prompt":"甲乙丙丁排成一列。甲在乙之前，丁在乙之后，丙在丁之后。紧跟乙的是谁？","options":["丁","甲","丙","无法确定"],"correct":0,"explanation":"四人的相对顺序被确定为甲、乙、丁、丙。","source":"百晓盛会原创"}'::jsonb, 'published'),
  ('letter-four', '{"knowledgeKey":"letter-four","category":"riddle","difficulty":"hard","kind":"choice","prompt":"四名书童各写一封只寄给其他三人之一的信。四人最后都恰收一封。两人可能互寄，最多能有几对互寄？","options":["两对","一对","三对","四对"],"correct":0,"explanation":"四个人可两两互寄，三对需要至少六个人。","source":"百晓盛会原创"}'::jsonb, 'published'),
  ('bells-together', '{"knowledgeKey":"bells-together","category":"riddle","difficulty":"hard","kind":"choice","prompt":"甲钟每 4 分钟响一次，乙钟每 6 分钟响一次。现在齐响，下一次齐响要等多久？","options":["12 分钟","10 分钟","18 分钟","24 分钟"],"correct":0,"explanation":"4 和 6 的最小公倍数是 12。","source":"百晓盛会原创"}'::jsonb, 'published'),
  ('square-courtyard', '{"knowledgeKey":"square-courtyard","category":"riddle","difficulty":"hard","kind":"choice","prompt":"一座方院四边各摆三盆花，四个角各有一盆且每盆只摆一次，一共摆了几盆？","options":["8 盆","12 盆","9 盆","6 盆"],"correct":0,"explanation":"四角被相邻两边各数一次，四边的 12 需减去 4。","source":"百晓盛会原创"}'::jsonb, 'published'),
  ('tea-labels', '{"knowledgeKey":"tea-labels","category":"riddle","difficulty":"hard","kind":"choice","prompt":"三只匣子分别只装龙井、普洱或各一份，三个标签全贴错。只拿一次，先从哪只匣中取可确定三匣内容？","options":["标签“两种”的匣","标签“龙井”的匣","标签“普洱”的匣","任选一匣"],"correct":0,"explanation":"“两种”标签肯定贴到了单一茶叶上，抽一份即可确定该匣，其余依标签全错推得。","source":"百晓盛会原创"}'::jsonb, 'published');
